15.8 Ajuste do modelo de regressão logística aos dados do exemplo de motivação

15.8.1 Utilizando o R

library(readxl)
library(ggplot2)
##
##
rm(list = ls())
#
horseshoe&lt;- read_excel("Dados/horseshoe_crab.xlsx")
str(horseshoe)
#
reglog1.hc&lt;- glm(y ~ width, 
                 family = binomial(link = "logit"), 
                 data = horseshoe)
summary(reglog1.hc)
#
## Grafico
ggplot(horseshoe, aes(x = width, y = y)) +
  geom_point() +
  geom_smooth(method = "glm",   
              method.args = list(family = "binomial"),
              se = FALSE, color = "red") +  
  labs( x = "Largura da carapaça (cm)",
        y = expression(hat(pi))) +
  theme_minimal()



